<?php
namespace qqworld_collector\module\collect_filter; class filter_by_regex extends filter { public function parse_regex_pattern($pattern) { $patterns = array( '/\\\\\(\\\!(.*?)\\\!\\\\\\)/i', '/\\\\\(\\\!(.*?)\\\!:\\\\\\*\\\\\\)/i', '/\\\\\(content:\\\!(.*?)\\\!\\\\\\)/i', '/\\\\\(content:\\\!(.*?)\\\!:\\\\\\*\\\\\\)/i' ); $replacements = array( '[^${1}]*?', '[^${1}]*', '([^${1}]*?)', '([^${1}]*)' ); $pattern = preg_replace($patterns, $replacements, $pattern); $preg = preg_match('/\\\\\(o:([^\)]*)\\\\\)/', $pattern, $match); if ($preg) { $pattern = str_replace($match[0], '['.str_replace('\|', '|', $match[1]).']', $pattern); } $patterns = array( '\(\^\)', '\(\$\)', '\(\*\)', '\(\*:\*\)', '\(d\)', '\(d:\*\)', '\(n\)', '\(n:\*\)', '\(w\)', '\(w:\*\)', '\(\.\)', '\(\.:\*\)', '\(c\)', '\(c:\*\)', '\(content\)', '\(content:\*\)', '\(content:d\)', '\(content:d:\*\)', '\(content:w\)', '\(content:w:\*\)', '\(content:\.\)', '\(content:\.:\*\)', '\(content:c\)', '\(content:c:\*\)', ); $replacements = array( '^', '$', '[\s\S]*?', '[\s\S]*', '\d*?', '\d*', '[\n\r\s\t]*?', '[\n\r\s\t]*', '\w*?', '\w*', '.*?', '.*', '[\u4e00-\u9fa5]*?', '[\u4e00-\u9fa5]*', ')[\s\S]*?(', ')[\s\S]*(', ')\d*?(', ')\d*(', ')\w*?(', ')\w*(', ').*?(', ').*(', ')[\u4e00-\u9fa5]*?(', ')[\u4e00-\u9fa5]*(', ); if ($this->pattern_has_content) { if ($this->replacement_has_content) { $replacements = array( '^', '$', '[\s\S]*?', '[\s\S]*', '\d*?', '\d*', '[\n\r\s\t]*?', '[\n\r\s\t]*', '\w*?', '\w*', '.*?', '.*', '[\u4e00-\u9fa5]*?', '[\u4e00-\u9fa5]*', ')([\s\S]*?)(', ')([\s\S]*)(', ')(\d*?)(', ')(\d*)(', ')(\w*?)(', ')(\w*)(', ')(.*?)(', ')(.*)(', ')([\u4e00-\u9fa5]*?)(', ')([\u4e00-\u9fa5]*)(', ); } $pattern = '/('.str_replace($patterns, $replacements, $pattern).')/i'; } else { $pattern = '/'.str_replace($patterns, $replacements, $pattern).'/i'; } return $pattern; } public function parse_regex_replacement($replacement) { if ($this->pattern_has_content) { if ($this->replacement_has_content) { $parts = explode('(content)', $replacement); $replacement = $parts[0].'${2}'.$parts[1]; } else { $replacement = '${1}' . $replacement . '${2}'; } } $replacement = apply_filters( 'qqworld-collector-collection-project-variable-filter', $replacement, 0 ); return $replacement; } public function parse_args($args) { $patterns = array(); $replacements = array(); foreach ($args as $arg) { extract($arg); $pattern = stripslashes($pattern); $pattern = str_replace(array('&amp;nbsp', '&amp;quot', '&amp;times', '&amp;sect'), array('&nbsp', '&quot', '&times', '&sect'), $pattern); $this->pattern_has_content = preg_match('/\(content.*?\)/i', $pattern); $this->replacement_has_content = preg_match('/\(content.*?\)/i', $replacement); $pattern = $this->core->encode_pattern($pattern); $pattern = $this->parse_regex_pattern($pattern); $patterns[] = $pattern; $replacements[] = $this->parse_regex_replacement($replacement); } return array($patterns, $replacements); } public function filter($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode) { if (!empty($args)) { list($patterns, $replacements) = $this->parse_args($args); $item = preg_replace($patterns, $replacements, $item); } return $item; } } ?>